using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["environment"] = "production",
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaAccess"] = false
        }
    };

    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(
        UriTemplate = "config://features",
        Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns the current feature flag settings.")]
    public static string GetFeatureFlags() =>
        JsonSerializer.Serialize(AppConfig["features"], new JsonSerializerOptions { WriteIndented = true });
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Checks whether a specific feature flag is enabled.")]
    public static string CheckFeature(
        [Description("The feature flag name to check (e.g. darkMode, betaAccess)")] string featureName)
    {
        var features = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaAccess"] = false
        };

        return features.TryGetValue(featureName, out var enabled)
            ? $"Feature '{featureName}' is {(enabled ? "enabled" : "disabled")}."
            : $"Feature '{featureName}' not found. Available: {string.Join(", ", features.Keys)}";
    }

    [McpServerTool(ReadOnly = true), Description("Lists all available configuration keys.")]
    public static string ListConfigKeys()
    {
        var keys = new[] { "environment", "maxRetries", "timeoutSeconds", "features" };
        return $"Available keys: {string.Join(", ", keys)}";
    }
}

